SELECT MIN(icustays.los) AS min_los FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_age = 93 AND icustays.los IS NOT NULL AND (admissions.admission_type = 'Pneumonia' OR admissions.admission_type = 'Acute Respiratory Distress Syndrome') AND (patients.anchor_year BETWEEN 88 AND 98);